    /** By Phosphor name — for icon keys that live in data (a tool, a section, a project). */
    fun of(name: String): ImageVector? = when (name) {
        "alarm" -> alarm
        "arrow-counter-clockwise" -> arrowCounterClockwise
        "arrow-elbow-down-right" -> arrowElbowDownRight
        "arrow-left" -> arrowLeft
        "arrow-up-right" -> arrowUpRight
        "arrow-up" -> arrowUp
        "arrows-down-up" -> arrowsDownUp
        "barbell" -> barbell
        "bell-ringing" -> bellRinging
        "bell" -> bell
        "bowl-food" -> bowlFood
        "brain" -> brain
        "broom" -> broom
        "cake" -> cake
        "calendar-blank" -> calendarBlank
        "caret-down" -> caretDown
        "caret-left" -> caretLeft
        "caret-right" -> caretRight
        "chart-bar" -> chartBar
        "check-circle" -> checkCircle
        "check-square" -> checkSquare
        "check" -> check
        "clock-counter-clockwise" -> clockCounterClockwise
        "clock" -> clock
        "cooking-pot" -> cookingPot
        "credit-card" -> creditCard
        "currency-inr" -> currencyInr
        "database" -> database
        "dots-three-vertical" -> dotsThreeVertical
        "fork-knife" -> forkKnife
        "google-logo" -> googleLogo
        "heartbeat" -> heartbeat
        "identification-card" -> identificationCard
        "image" -> image
        "kanban" -> kanban
        "list" -> list
        "lock" -> lock
        "magnifying-glass" -> magnifyingGlass
        "map-pin" -> mapPin
        "microphone" -> microphone
        "note-pencil" -> notePencil
        "package" -> `package`
        "pencil-simple" -> pencilSimple
        "plus" -> plus
        "push-pin" -> pushPin
        "question" -> question
        "receipt" -> receipt
        "repeat" -> repeat
        "ruler" -> ruler
        "scales" -> scales
        "shield-check" -> shieldCheck
        "sign-out" -> signOut
        "sparkle" -> sparkle
        "star" -> star
        "sun-horizon" -> sunHorizon
        "user" -> user
        "users" -> users
        "wallet" -> wallet
        "x" -> x
        else -> null
    }
}

